sealed class AppleBluetoothRestorationPreparationOutcome {

    object Prepared : AppleBluetoothRestorationPreparationOutcome()


    object AlreadyPrepared : AppleBluetoothRestorationPreparationOutcome()


    object AlreadyRunning : AppleBluetoothRestorationPreparationOutcome()


    data class Failed(
        val `stage`: rs.reticulum.prns.app.bindings.AppleBluetoothRestorationPreparationFailureStage,
        val `detail`: kotlin.String) : AppleBluetoothRestorationPreparationOutcome()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAppleBluetoothRestorationPreparationOutcome : FfiConverterRustBuffer<AppleBluetoothRestorationPreparationOutcome>{
    override fun read(buf: ByteBuffer): AppleBluetoothRestorationPreparationOutcome {
        return when(buf.getInt()) {
            1 -> AppleBluetoothRestorationPreparationOutcome.Prepared
            2 -> AppleBluetoothRestorationPreparationOutcome.AlreadyPrepared
            3 -> AppleBluetoothRestorationPreparationOutcome.AlreadyRunning
            4 -> AppleBluetoothRestorationPreparationOutcome.Failed(
                FfiConverterTypeAppleBluetoothRestorationPreparationFailureStage.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppleBluetoothRestorationPreparationOutcome) = when(value) {
        is AppleBluetoothRestorationPreparationOutcome.Prepared -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AppleBluetoothRestorationPreparationOutcome.AlreadyPrepared -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AppleBluetoothRestorationPreparationOutcome.AlreadyRunning -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is AppleBluetoothRestorationPreparationOutcome.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeAppleBluetoothRestorationPreparationFailureStage.allocationSize(value.`stage`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: AppleBluetoothRestorationPreparationOutcome, buf: ByteBuffer) {
        when(value) {
            is AppleBluetoothRestorationPreparationOutcome.Prepared -> {
                buf.putInt(1)
                Unit
            }
            is AppleBluetoothRestorationPreparationOutcome.AlreadyPrepared -> {
                buf.putInt(2)
                Unit
            }
            is AppleBluetoothRestorationPreparationOutcome.AlreadyRunning -> {
                buf.putInt(3)
                Unit
            }
            is AppleBluetoothRestorationPreparationOutcome.Failed -> {
                buf.putInt(4)
                FfiConverterTypeAppleBluetoothRestorationPreparationFailureStage.write(value.`stage`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





